const List<String> framePages = <String>['CenterHomePage'];

/// Features on for every license type that don't, on their own, make a license worth listing (Q3).
const List<String> licensePickerIgnores = <String>['sign_in', 'license_picker', 'demo_mode', 'debug_tools'];

/// Whether [name] is on for a license of [licenseType] (FR-3). An unknown name is off.
bool featureOnForLicense(String name, String licenseType, {Map<String, Feature> table = features}) {
  final feature = table[name];
  return feature != null && feature.onPhone.contains(licenseType);
}

/// Whether the license picker lists licenses of [licenseType]: some feature beyond [licensePickerIgnores] is on
/// for it (FR-3, Q3).
bool licenseTypeListed(String licenseType, {Map<String, Feature> table = features}) =>
    table.values.any((f) => !licensePickerIgnores.contains(f.name) && f.onPhone.contains(licenseType));
